## Parsing and Executing Text Commands

A command parser splits input into a command word and arguments, then dispatches to the right handler. Each handler parses its own arguments and returns Result.

### The Command Set

1. **SAY** — echo the argument back
2. **ADD** — add two numbers
3. **SUB** — subtract two numbers
4. **RANDOM** — pick a random number between min and max

### Splitting the Input

```xiom
fn parse_command(input: Str) -> Result[Str, Str] {
  if string.str_len(input) == 0 {
    return Err("Empty command");
  }

  let space = 0;
  let i = 0;
  while i < string.str_len(input) {
    if string.str_slice(input, i, i + 1) == " " && space == 0 {
      space = i;
    }
    i = i + 1;
  }

  let cmd = "";
  let args = "";
  if space == 0 {
    cmd = input;
    args = "";
  }
  else {
    cmd = string.str_slice(input, 0, space);
    args = string.str_slice(input, space + 1, string.str_len(input));
  }

  if cmd == "SAY" {
    return Ok("You said: " + args);
  }
  elif cmd == "ADD" {
    return handle_math(args, "add");
  }
  elif cmd == "SUB" {
    return handle_math(args, "sub");
  }
  elif cmd == "RANDOM" {
    return handle_random(args);
  }
  else {
    return Err("Unknown command: " + cmd);
  }
}
```

### The Math Handler

```xiom
fn handle_math(args: Str, op: Str) -> Result[Str, Str] {
  let inner_space = 0;
  let j = 0;
  while j < string.str_len(args) {
    if string.str_slice(args, j, j + 1) == " " {
      inner_space = j;
    }
    j = j + 1;
  }

  if inner_space == 0 {
    return Err(op + " needs two numbers");
  }

  let a_str = string.str_slice(args, 0, inner_space);
  let b_str = string.str_slice(args, inner_space + 1, string.str_len(args));

  let a = string.str_to_int(a_str)?;
  let b = string.str_to_int(b_str)?;

  if op == "add" {
    return Ok(string.int_to_str(a) + " + " + string.int_to_str(b) + " = " + string.int_to_str(a + b));
  }
  else {
    return Ok(string.int_to_str(a) + " - " + string.int_to_str(b) + " = " + string.int_to_str(a - b));
  }
}
```

### The Random Handler

```xiom
fn handle_random(args: Str) -> Result[Str, Str] {
  let inner_space = 0;
  let j = 0;
  while j < string.str_len(args) {
    if string.str_slice(args, j, j + 1) == " " {
      inner_space = j;
    }
    j = j + 1;
  }

  if inner_space == 0 {
    return Err("RANDOM needs min and max");
  }

  let min_str = string.str_slice(args, 0, inner_space);
  let max_str = string.str_slice(args, inner_space + 1, string.str_len(args));

  let min = string.str_to_int(min_str)?;
  let max = string.str_to_int(max_str)?;

  if min > max {
    return Err("Min must be <= max");
  }

  let result = math.random_range(min, max);
  return Ok("Random (" + string.int_to_str(min) + "-" + string.int_to_str(max) + "): " + string.int_to_str(result));
}
```

### Running Commands

```xiom
fn main() -> Int {
  match parse_command("SAY hello world") {
    Ok(out) => { io.println(out); }
    Err(e) => { io.println(e); }
  }
  match parse_command("ADD 5 3") {
    Ok(out) => { io.println(out); }
    Err(e) => { io.println(e); }
  }
  match parse_command("RANDOM 1 10") {
    Ok(out) => { io.println(out); }
    Err(e) => { io.println(e); }
  }
  match parse_command("MUL 4 2") {
    Ok(out) => { io.println(out); }
    Err(e) => { io.println(e); }
  }
  return 0;
}
```

