use xiom.io;

use xiom.string;
use xiom.math;
fn parse_command(input: Str) -> Result[Str, Str] {
  if string.str_len(input) == 0 {
    return Err("Empty command");
  }

  let space = 0;
  let i = 0;
  while i < string.str_len(input) {
    if string.str_slice(input, i, i + 1) == " " && space == 0 {
      space = i;
    }
    i = i + 1;
  }

  let cmd = "";
  let args = "";
  if space == 0 {
    cmd = input;
    args = "";
  }
  else {
    cmd = string.str_slice(input, 0, space);
    args = string.str_slice(input, space + 1, string.str_len(input));
  }

  if cmd == "SAY" {
    return Ok(args);
  }
  elif cmd == "ADD" {
    let inner_space = 0;
    let j = 0;
    while j < string.str_len(args) {
      if string.str_slice(args, j, j + 1) == " " { inner_space = j; }
      j = j + 1;
    }
    if inner_space == 0 { return Err("ADD needs two numbers"); }
    let a = string.str_to_int(string.str_slice(args, 0, inner_space))?;
    let b = string.str_to_int(string.str_slice(args, inner_space + 1, string.str_len(args)))?;
    return Ok(to_string(a + b));
  }
  elif cmd == "RANDOM" {
    let inner_space = 0;
    let j = 0;
    while j < string.str_len(args) {
      if string.str_slice(args, j, j + 1) == " " { inner_space = j; }
      j = j + 1;
    }
    if inner_space == 0 { return Err("RANDOM needs two numbers"); }
    let min = string.str_to_int(string.str_slice(args, 0, inner_space))?;
    let max = string.str_to_int(string.str_slice(args, inner_space + 1, string.str_len(args)))?;
    return Ok(to_string(math.random_range(min, max)));
  }
  else {
    return Err("Unknown command: " + cmd);
  }
}

fn main() -> Int {
  match parse_command("ADD 5 3") {
    Ok(out) => { io.println(out.to_str()); return 200; }
    Err(e) => { io.println(e.to_str()); return 400; }
  }
}
